<?php declare(strict_types=1);
function lh_has_column(PDO $db,string $table,string $column):bool{$q=$db->prepare("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?");$q->execute([$table,$column]);return (int)$q->fetchColumn()>0;}
function lh_course(PDO $db,string $slug):?array{$q=$db->prepare("SELECT c.*,lc.name category_name,lc.icon category_icon FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE c.slug=? AND c.enabled=1 LIMIT 1");$q->execute([$slug]);return $q->fetch(PDO::FETCH_ASSOC)?:null;}
function lh_lessons(PDO $db,int $courseId):array{$hasCh=lh_has_column($db,'learning_lessons','chapter_id');$hasTable=(bool)$db->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='learning_chapters'")->fetchColumn();if($hasCh&&$hasTable){$sql="SELECT l.*,ch.title chapter_title FROM learning_lessons l JOIN learning_chapters ch ON ch.id=l.chapter_id WHERE ch.course_id=? AND l.enabled=1 ORDER BY ch.sort_order,ch.id,l.sort_order,l.id";}else{$sql="SELECT l.* FROM learning_lessons l WHERE l.course_id=? AND l.enabled=1 ORDER BY l.sort_order,l.id";}$q=$db->prepare($sql);$q->execute([$courseId]);return $q->fetchAll(PDO::FETCH_ASSOC);}
function lh_lesson(PDO $db,string $slug):?array{$hasCh=lh_has_column($db,'learning_lessons','chapter_id');$hasTable=(bool)$db->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='learning_chapters'")->fetchColumn();if($hasCh&&$hasTable){$sql="SELECT l.*,c.title course_title,c.slug course_slug,lc.name category_name FROM learning_lessons l JOIN learning_chapters ch ON ch.id=l.chapter_id JOIN learning_courses c ON c.id=ch.course_id LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE l.slug=? AND l.enabled=1 AND c.enabled=1 LIMIT 1";}else{$sql="SELECT l.*,c.title course_title,c.slug course_slug,lc.name category_name FROM learning_lessons l JOIN learning_courses c ON c.id=l.course_id LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE l.slug=? AND l.enabled=1 AND c.enabled=1 LIMIT 1";}$q=$db->prepare($sql);$q->execute([$slug]);return $q->fetch(PDO::FETCH_ASSOC)?:null;}
function lh_lesson_nav(PDO $db,int $courseId,int $lessonId):array{$all=lh_lessons($db,$courseId);foreach($all as $i=>$r)if((int)$r['id']===$lessonId)return ['all'=>$all,'previous'=>$all[$i-1]??null,'next'=>$all[$i+1]??null,'position'=>$i+1];return ['all'=>$all,'previous'=>null,'next'=>null,'position'=>0];}
?>